#include <iostream>

// Demonstrates pass-by-value: modifications do not alter caller's variables
void incrementAndPrint(char symbol, int count) {
    std::cout << "Inside function before modification: symbol = " << symbol 
              << ", count = " << count << "\n";

    // Modify local parameter copies
    count += 2;
    symbol = '*';

    std::cout << "Inside function after modification: symbol = " << symbol 
              << ", count = " << count << "\n";
}

int main() {
    char symbol = '#';
    int count = 3;

    std::cout << "Caller before invoke: symbol = " << symbol 
              << ", count = " << count << "\n";

    // Pass arguments by value (identical variable names to parameters)
    incrementAndPrint(symbol, count);

    std::cout << "Caller after invoke: symbol = " << symbol 
              << ", count = " << count << "\n";

    return 0;
}

