#include <iostream>
#include <iomanip>

// Compute greatest common divisor of two integers (Listing 6.4)
int gcd(int n1, int n2) {
    int currentGcd = 1;
    int k = 2;
    while (k <= n1 && k <= n2) {
        if (n1 % k == 0 && n2 % k == 0) {
            currentGcd = k;
        }
        k++;
    }
    return currentGcd;
}

// Check whether a number is prime (Listing 6.5)
bool isPrime(int number) {
    for (int divisor = 2; divisor <= number / 2; divisor++) {
        if (number % divisor == 0) {
            return false;
        }
    }
    return true;
}

// Print the first numberOfPrimes primes formatted into lines (Listing 6.5)
void printPrimeNumbers(int numberOfPrimes) {
    const int NUMBER_OF_PRIMES_PER_LINE = 10;
    int count = 0;
    int number = 2;

    while (count < numberOfPrimes) {
        if (isPrime(number)) {
            count++;
            if (count % NUMBER_OF_PRIMES_PER_LINE == 0) {
                std::cout << std::setw(4) << number << "\n";
            } else {
                std::cout << std::setw(4) << number;
            }
        }
        number++;
    }
}

int main() {
    int a = 45;
    int b = 75;
    std::cout << "GCD of " << a << " and " << b << " is " << gcd(a, b) << "\n";

    std::cout << "The first 15 prime numbers are:\n";
    printPrimeNumbers(15);

    return 0;
}
